@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation
@using sv_e50d97fd368943069bc27814b5515fd2.Services

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<nav>
    <a href="/recipes/1?sort=@currentSort">Italian</a> |
    <a href="/recipes/2?sort=@currentSort">Indian</a> |
    <a href="/recipes/3?sort=@currentSort">Mexican</a>
</nav>

<div style="margin: 1rem 0;">
    <label>Sort:
        <select @bind="SelectedSort" @bind:after="OnSortChanged">
            <option value="newest">Newest</option>
            <option value="popular">Popular</option>
        </select>
    </label>
</div>

@if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@errorMessage</p>
        <button class="btn btn-outline-danger" @onclick="Retry">Retry</button>
    </div>
}
else if (recipes is null)
{
    <p><em>Loading recipes...</em></p>
}
else
{
    @if (isRefreshing)
    {
        <p><em>Refreshing…</em></p>
    }

    <table class="table">
        <thead>
            <tr>
                <th>Title</th>
                <th>Description</th>
                <th>Prep Time (min)</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var recipe in DisplayedRecipes)
            {
                <tr>
                    <td>@recipe.Title</td>
                    <td>@recipe.Description</td>
                    <td>@recipe.PrepTimeMinutes</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? recipes;
    private bool isRefreshing;
    private string? errorMessage;
    private string currentSort = "newest";
    private string SelectedSort
    {
        get => currentSort;
        set => currentSort = value;
    }

    private int loadedCuisineId;
    private CancellationTokenSource? cts;

    private IEnumerable<Recipe> DisplayedRecipes => currentSort == "popular"
        ? recipes!.OrderBy(r => r.PrepTimeMinutes)
        : recipes!.OrderByDescending(r => r.Id);

    protected override async Task OnParametersSetAsync()
    {
        var sort = string.IsNullOrEmpty(Sort) ? "newest" : Sort;
        currentSort = sort is "newest" or "popular" ? sort : "newest";

        // Only reload data when cuisine actually changes
        if (CuisineId == loadedCuisineId && recipes is not null)
            return;

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request
        cts?.Cancel();
        cts?.Dispose();
        cts = new CancellationTokenSource();
        var token = cts.Token;

        errorMessage = null;
        isRefreshing = recipes is not null;
        loadedCuisineId = CuisineId;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(CuisineId, token);
            token.ThrowIfCancellationRequested();
            recipes = result;
            isRefreshing = false;
        }
        catch (OperationCanceledException) when (token.IsCancellationRequested)
        {
            // Request was superseded — do nothing
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            isRefreshing = false;
            errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            isRefreshing = false;
            errorMessage = "Something went wrong loading recipes. Please try again.";
        }
    }

    private async Task Retry()
    {
        await LoadRecipesAsync();
    }

    private void OnSortChanged()
    {
        Navigation.NavigateTo($"/recipes/{CuisineId}?sort={currentSort}", replace: true);
    }

    public void Dispose()
    {
        cts?.Cancel();
        cts?.Dispose();
    }
}

